// Enforce basic requirements: args must be valid with argv[0] present.
if (!args || args->argc < 1 || !args->argv || !args->argv[0]) { FUZZ_BAIL(); }

// Call the help printer; this may print to stdout and may inspect/modify args.
fuse_lib_help(args);

// Track that args have been validated to contain argv[0]
FUZZ_SET_ATTR_INT(args, "has_argv0", 1);

// Return args back to the pool since we did not free/consume it.
/* Validation: The stub checks args invariants (argc>=1, argv[0] non-null),
   invokes fuse_lib_help, and returns args unchanged, preserving ownership. */

// Validate args per API: must have argv[0].
if (!args || args->argc < 1 || !args->argv || !args->argv[0]) { FUZZ_BAIL(); }

// Build a minimal operations table; all handlers optional, zero-init is valid.
struct fuse_operations ops = {};

// Use op_size matching this compilation unit's view of fuse_operations.
size_t op_size = sizeof(ops);

// user_data may be arbitrary; pass NULL for safety.
void *user_data = NULL;

// Create the FUSE handle via the inline selector. This should not mount.
struct fuse *fuse = fuse_new_fn(args, &ops, op_size, user_data);

// If --help or invalid options were present, fuse_new_fn may return NULL.
if (!fuse) { FUZZ_BAIL(); }

// Track basic lifecycle attributes on the new handle.
FUZZ_SET_ATTR_INT(fuse, "created", 1);
FUZZ_SET_ATTR_INT(fuse, "mounted", 0);

// Preserve args (we did not consume/free it) and return the new handle.
/* Validation: Ensures args invariants, uses a zero-initialized ops with
   correct op_size, bails on NULL return, and returns both args and fuse
   to keep ownership/lifetime consistent for further stubs. */

// Validate args per API: must have argv[0] (may be empty string but non-null).
if (!args || args->argc < 1 || !args->argv || !args->argv[0]) { FUZZ_BAIL(); }

// Prepare a minimal operations vtable; zero is allowed (all callbacks optional).
struct fuse_operations ops = {};
size_t op_size = sizeof(ops);

// Pass NULL user_data; init hook may override later when actually used.
void *user_data = NULL;

// Create the FUSE handle using the public macro/inline entry.
struct fuse *fuse = fuse_new(args, &ops, op_size, user_data);
if (!fuse) { FUZZ_BAIL(); }

// Set lifecycle attributes for downstream stubs.
FUZZ_SET_ATTR_INT(fuse, "created", 1);
FUZZ_SET_ATTR_INT(fuse, "mounted", 0);

// Return both args (unchanged) and the new fuse handle.
/* Validation: Checks args invariants, uses correct op_size, handles NULL
   return with FUZZ_BAIL, and returns persistent objects with attributes set. */

// Validate basic handle lifecycle. We accept both mounted and unmounted handles for this call.
if (!fuse || !FUZZ_GET_ATTR_INT(fuse, "created")) { FUZZ_BAIL(); }

// Generate a path (absolute or relative is allowed). Ensure non-empty and bounded size.
std::string p = FUZZ_PARAM_STR();
if (p.empty()) { FUZZ_BAIL(); }
if (p.size() > 1024) p.resize(1024);

// Invoke the API. Nonzero/negative return is allowed per API; do not assert on value.
( void ) fuse_invalidate_path(fuse, p.c_str());

// Preserve fuse for further use.
/* Validation: Ensures a valid FUSE handle and a non-empty path, calls the function, and returns the handle back to the pool. */

// Require a valid created handle.
if (!fuse || !FUZZ_GET_ATTR_INT(fuse, "created")) { FUZZ_BAIL(); }

// Start the cleanup thread; multiple starts may fail, that's fine. Don't assert on return value.
( void ) fuse_start_cleanup_thread(fuse);

// Mark that a cleanup thread may be running to help downstream stubs make decisions.
FUZZ_SET_ATTR_INT(fuse, "cleanup_thread_started", 1);
/* Validation: Checks handle validity, calls the starter, and preserves the handle with an attribute hint. */

// Require a valid created handle.
if (!fuse || !FUZZ_GET_ATTR_INT(fuse, "created")) { FUZZ_BAIL(); }

// Stop the thread if it was started. Safe to call even if not started.
fuse_stop_cleanup_thread(fuse);

// Update attribute hint.
FUZZ_SET_ATTR_INT(fuse, "cleanup_thread_started", 0);
/* Validation: Ensures valid handle, invokes stop (idempotent), and returns handle. */

// Require a valid created handle.
if (!fuse || !FUZZ_GET_ATTR_INT(fuse, "created")) { FUZZ_BAIL(); }

// Run a cleanup pass; return value is advisory (seconds until next), ignore here.
( void ) fuse_clean_cache(fuse);

/* Validation: Validates input handle and executes cleanup without altering ownership. */

// Enforce that fs is a valid fuse_fs created by fuse_fs_new (tracked out-of-band).
if (!fs || !FUZZ_GET_ATTR_INT(fs, "fs_valid")) { FUZZ_BAIL(); }

// Prepare inputs
std::string path = FUZZ_PARAM_STR(); if (path.empty()) path = "/";
struct stat stbuf{};
struct fuse_file_info fi{}; // optional; may be ignored by implementation

( void ) fuse_fs_getattr(fs, path.c_str(), &stbuf, &fi);

/* Validation: Requires a valid fs handle and non-empty path, uses stack-allocated stat and fi, and returns fs. */

