// Old and new paths must be non-empty; they may or may not exist in the FS.
std::string oldp = FUZZ_PARAM_STR(); if (oldp.empty()) oldp = "/a";
std::string newp = FUZZ_PARAM_STR(); if (newp.empty()) newp = "/b";

// Flags: combine supported bits (0, RENAME_NOREPLACE(1), RENAME_EXCHANGE(2)).
unsigned int flags = (unsigned int)(*FUZZ_PARAM(unsigned int) & 0x3);

( void ) fuse_fs_rename(fs, oldp.c_str(), newp.c_str(), flags);

/* Validation: Ensures fs validity, passes bounded flags and non-empty paths, returns fs. */

if (!fs || !FUZZ_GET_ATTR_INT(fs, "fs_valid")) { FUZZ_BAIL(); }
std::string p = FUZZ_PARAM_STR(); if (p.empty()) p = "/file";
( void ) fuse_fs_unlink(fs, p.c_str());
/* Validation: Valid fs and non-empty path; returns fs. */

if (!fs || !FUZZ_GET_ATTR_INT(fs, "fs_valid")) { FUZZ_BAIL(); }
std::string p = FUZZ_PARAM_STR(); if (p.empty()) p = "/dir";
( void ) fuse_fs_rmdir(fs, p.c_str());
/* Validation: Valid fs and non-empty path; returns fs. */

if (!fs || !FUZZ_GET_ATTR_INT(fs, "fs_valid")) { FUZZ_BAIL(); }
std::string target = FUZZ_PARAM_STR(); if (target.empty()) target = "/target";
std::string linkpath = FUZZ_PARAM_STR(); if (linkpath.empty()) linkpath = "/link";
( void ) fuse_fs_symlink(fs, target.c_str(), linkpath.c_str());
/* Validation: Valid fs and non-empty strings; returns fs. */

if (!fs || !FUZZ_GET_ATTR_INT(fs, "fs_valid")) { FUZZ_BAIL(); }
std::string oldp = FUZZ_PARAM_STR(); if (oldp.empty()) oldp = "/src";
std::string newp = FUZZ_PARAM_STR(); if (newp.empty()) newp = "/dst";
( void ) fuse_fs_link(fs, oldp.c_str(), newp.c_str());
/* Validation: Valid fs and paths; returns fs. */

