std::string p = FUZZ_PARAM_STR(); // may be NULL if removed; we provide best-effort
int datasync = (int)(*FUZZ_PARAM(unsigned int) & 1u);
struct fuse_file_info fi{};
( void ) fuse_fs_fsync(fs, p.empty() ? nullptr : p.c_str(), datasync, &fi);
/* Validation: Valid fs; boolean datasync; returns fs. */

if (!fs || !FUZZ_GET_ATTR_INT(fs, "fs_valid")) { FUZZ_BAIL(); }
std::string p = FUZZ_PARAM_STR(); if (p.empty()) p = "/file";
struct fuse_file_info fi{};
( void ) fuse_fs_flush(fs, p.c_str(), &fi);
/* Validation: Valid fs; returns fs. */

