    int a = (int)*FUZZ_PARAM(unsigned int);
    unsigned int b = *FUZZ_PARAM(unsigned int);
    // Two integer arguments with matching specifiers
    fuse_log(level, "value=%d hex=%x\n", a, b);
} else if (sel == 2) {
    // Mixed types; float promoted to double in varargs
    double d;
    memcpy(&d, FUZZ_PARAM(unsigned long long), sizeof(d));
    long l = (long)(*(FUZZ_PARAM(unsigned long long)));
    std::string name = FUZZ_PARAM_STR();
    fuse_log(level, "pi=%.3f name=%s num=%ld\n", d, name.c_str(), l);
} else {
    // No arguments
    fuse_log(level, "literal message\n");
}

// ident analogous to openlog(3) ident
std::string ident = FUZZ_PARAM_STR();
// option and facility: use small bounded integers; platform will validate
int option = (int)(*FUZZ_PARAM(unsigned int) & 0xFF);
int facility = (int)(*FUZZ_PARAM(unsigned int) & 0xFF);

// Enable syslog backend globally
fuse_log_enable_syslog(ident.c_str(), option, facility);

// Construct a FUSE handle from validated args.
// Requirements: args must have argv[0] present (may be empty string but non-null).
if (!args || args->argc < 1 || !args->argv || !args->argv[0]) { FUZZ_BAIL(); }

// Prepare a minimal operations table; all callbacks optional for construction.
struct fuse_operations ops = {};
size_t op_size = sizeof(ops);

// user_data is arbitrary; pass NULL to keep lifecycle simple.
void *user_data = NULL;

// Create the handle via the public API (macro/inline wrapper). This does not mount.
struct fuse *fuse = fuse_new(args, &ops, op_size, user_data);
if (!fuse) { FUZZ_BAIL(); }

// Track lifecycle attributes for downstream usage.
FUZZ_SET_ATTR_INT(fuse, "created", 1);
FUZZ_SET_ATTR_INT(fuse, "mounted", 0);

// We did not consume/free args; return both objects to the pool.
/* Validation: Ensures args invariants, creates a FUSE handle with correct op_size,
   bails on NULL, and annotates lifecycle. */

// User-managed allocation: allocate and initialize a struct fuse_lowlevel_ops.
struct fuse_lowlevel_ops *op = (struct fuse_lowlevel_ops*)calloc(1, sizeof(*op));
if (!op) { FUZZ_BAIL(); }

// Provide a few minimal, no-op handlers to cover function pointer wiring.
op->init = +[](void * /*userdata*/, struct fuse_conn_info * /*conn*/){ };
op->destroy = +[](void * /*userdata*/){ };
// Handlers that accept a request; they should not call reply APIs here.
op->lookup = +[](fuse_req_t /*req*/, fuse_ino_t /*parent*/, const char * /*name*/){ };
op->getattr = +[](fuse_req_t /*req*/, fuse_ino_t /*ino*/, struct fuse_file_info * /*fi*/){ };
op->read = +[](fuse_req_t /*req*/, fuse_ino_t /*ino*/, size_t /*size*/, off_t /*off*/, struct fuse_file_info * /*fi*/){ };
op->write = +[](fuse_req_t /*req*/, fuse_ino_t /*ino*/, const char * /*buf*/, size_t /*size*/, off_t /*off*/, struct fuse_file_info * /*fi*/){ };
op->statfs = +[](fuse_req_t /*req*/, fuse_ino_t /*ino*/){ };

// Attribute to mark that this vtable is intentionally minimal but valid.
FUZZ_SET_ATTR_INT(op, "llops_valid", 1);
/* Validation: Allocates a heap object, assigns captureless functions matching
   required signatures, and tags the object for downstream stubs. */

// There is no public constructor for fuse_req_t; fabricate a placeholder that
// downstream reply stubs can reason about via attributes. We avoid calling any
// libfuse functions here.

// Allocate storage for a fuse_req_t handle value (opaque pointer) and ensure non-null.
fuse_req_t *req = (fuse_req_t*)malloc(sizeof(fuse_req_t));
if (!req) { FUZZ_BAIL(); }

// Synthesize a non-null opaque handle value from fuzz data.
uintptr_t cookie = (uintptr_t)(0x100u + (*FUZZ_PARAM(unsigned int)));
*req = (fuse_req_t)(void*)cookie;

// Tag the underlying opaque handle (not the pointer-to-handle) with operation context
// so reply helpers can validate usage. Choose among supported ops.
int which = (int)(*FUZZ_PARAM(unsigned int) % 4u);
const char *opname = (which == 0 ? "ioctl" : (which == 1 ? "poll" : (which == 2 ? "lseek" : "statx")));
FUZZ_SET_ATTR_STR(*req, "op", opname);
FUZZ_SET_ATTR_INT(*req, "replied", 0);

/* Validation: Produces a stable, non-null opaque request handle and annotates it
   with an operation name and reply state for downstream checks. */

// Produce an opaque pointer instance used by APIs that accept void* handles.
// Specifically, create a stand-in for struct fuse_pollhandle* used by notify APIs.
void *ph = calloc(1, 16);
if (!ph) { FUZZ_BAIL(); }

// Constrain usage by tagging it as a poll handle surrogate.
FUZZ_SET_ATTR_INT(ph, "is_pollhandle", 1);

/* Validation: Allocates a small opaque block, marks it with a required attribute
   so only compatible endpoints will accept it. */

// Construct a valid fuse_args: argc>=1, argv[0] present, NULL-terminated.
struct fuse_args *args = (struct fuse_args*)calloc(1, sizeof(*args));
if (!args) { FUZZ_BAIL(); }

int argc = 1 + (int)(*FUZZ_PARAM(unsigned int) % 4u); // 1..4 args beyond argv[0]
if (argc < 1) argc = 1;

// Build strings and allocate argv; library may modify/free when allocated!=0
args->argc = argc;
args->allocated = 1;
args->argv = (char**)calloc((size_t)argc + 1, sizeof(char*));
if (!args->argv) { FUZZ_BAIL(); }

// Ensure argv[0] exists; other args arbitrary but bounded in size.
for (int i = 0; i < argc; ++i) {
    std::string s = FUZZ_PARAM_STR();
    if (s.size() > 256) s.resize(256);
    if (i == 0 && s.empty()) s = "fuzzfs"; // enforce presence of argv[0]
    char *dup = (char*)malloc(s.size() + 1);
    if (!dup) { FUZZ_BAIL(); }
    memcpy(dup, s.data(), s.size()); dup[s.size()] = '\0';
    args->argv[i] = dup;
}
args->argv[argc] = nullptr; // NULL-terminate

// Mark attribute to indicate argv[0] presence for downstream validators.
FUZZ_SET_ATTR_INT(args, "has_argv0", 1);

/* Validation: Produces a heap-allocated fuse_args with argv[0] guaranteed,
   NULL-terminated argv, and allocated=1 so API utilities may free/resize it. */

