import os
import random
import string
from typing import List

# Data type: filesystem path string
# We need to generate interesting, valid path strings that exercise different
# code paths in libfuse high- and low-level helpers. The fuzzer stubs call
# FUZZ_PARAM_STR() for many parameters that are paths, xattr names, ioctl data
# seeding, etc. Our generator will return a bytes buffer that the harness will
# consume to produce strings and numbers. We therefore pack a sequence of
# newline-separated path-like strings plus some auxiliary tokens used by the
# stubs (e.g., xattr tails, payloads). All strings are valid UTF-8 and within
# 4096 bytes total. No mutation after generation; inputs aim to be valid.

# Strategy:
# - Provide a mix of absolute and relative paths.
# - Include directories, files, hidden files, symlinks-like names, dot segments,
#   long components, Unicode, special characters allowed in POSIX filenames,
#   and trailing slashes where meaningful.
# - Provide pairs of related paths for operations like rename/link/copy.
# - Include common xattr name tails and small data payload lines for write/ioctl.
# - Keep each entry length reasonable; ensure non-empty strings.

SAFE_CHARS = string.ascii_letters + string.digits + "-_.,+@%:="


def _rand_filename(r: random.Random, min_len: int = 1, max_len: int = 20) -> str:
    n = r.randint(min_len, max_len)
    # Ensure not all dots; reserve reserved names like "." and ".." only when intended
    s = ''.join(r.choice(SAFE_CHARS) for _ in range(n))
    if set(s) == {'.'} or s in (".", ".."):
        s = "file"
    return s


def _rand_component(r: random.Random) -> str:
    choice = r.randint(0, 8)
    if choice == 0:
        return "."
    if choice == 1:
        return ".."
    if choice == 2:
        # include some unicode
        pool = ["naïve", "😀", "δ", "スペース", "编号123"]
        return r.choice(pool)
    if choice == 3:
        return _rand_filename(r, 5, 40)
    if choice == 4:
        # long component (but safe)
        return _rand_filename(r, 40, 80)
    if choice == 5:
        return "hidden_" + _rand_filename(r, 1, 15)
    if choice == 6:
        return _rand_filename(r, 1, 10) + ".log"
    if choice == 7:
        return _rand_filename(r, 1, 10) + ".d"
    return _rand_filename(r, 1, 12)


def _make_path(r: random.Random, absolute: bool) -> str:
    depth = r.randint(0, 5)
    comps: List[str] = []
    for _ in range(depth):
        comps.append(_rand_component(r))
    # Ensure we have at least one component for non-root
    if not comps:
        comps = ["file" if not absolute else ""]
    path = ("/" if absolute else "") + "/".join([c for c in comps if c != ""]) 
    # Randomly add a trailing slash if it looks like a directory path request
    if r.random() < 0.2 and path and not path.endswith('/'):
        path += '/'
    if path == "":
        path = "/"
    return path


def _pair_paths(r: random.Random) -> List[str]:
    # Create two related paths for rename/link/copy
    base_dir = _make_path(r, True)
    if not base_dir.endswith('/'):
        base_dir = base_dir + '/'
    a = base_dir + _rand_filename(r, 1, 12)
    b_variant = r.randint(0, 3)
    if b_variant == 0:
        b = base_dir + _rand_filename(r, 1, 12)
    elif b_variant == 1:
        # different directory
        b = _make_path(r, True)
        if not b.endswith('/'):
            b += '/'
        b += _rand_filename(r, 1, 12)
    elif b_variant == 2:
        # exchange-like: sibling
        b = base_dir + _rand_filename(r, 1, 12)
    else:
        # relative counterpart
        b = _make_path(r, False)
    return [a, b]


def _xattr_tail(r: random.Random) -> str:
    # Construct safe xattr name tail
    head = _rand_filename(r, 3, 16)
    # allow dots/underscores
    tail = head
    if r.random() < 0.4:
        tail += "." + _rand_filename(r, 2, 8)
    return tail


def _payload(r: random.Random, min_len: int, max_len: int) -> str:
    n = r.randint(min_len, max_len)
    # Use printable bytes to remain valid UTF-8/ASCII
    alphabet = string.printable.strip()
    s = ''.join(r.choice(alphabet) for _ in range(n))
    if not s:
        s = "x"
    return s


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    lines: List[str] = []

    # Common anchor paths
    anchors = [
        "/", "/file", "/dir", "/a/b/c", "relative.txt", "./rel/./path", "../up/dir",
        "/tmp/fuse_test", "/var/lib/fuse/cache", "/mnt/fusemount",
    ]
    lines.extend(anchors)

    # A variety of absolute and relative paths
    for _ in range(20):
        lines.append(_make_path(r, True))
        lines.append(_make_path(r, False))

    # Pairs for operations needing two paths
    for _ in range(6):
        lines.extend(_pair_paths(r))

    # Names for mkdir/mknod/create targets
    for _ in range(6):
        parent = _make_path(r, True)
        if not parent.endswith('/'):
            parent += '/'
        lines.append(parent + _rand_filename(r, 1, 12))

    # Symlink target-like strings (can be absolute or relative)
    for _ in range(6):
        lines.append(_make_path(r, r.random() < 0.5))

    # Xattr tails used by stubs; they prepend user.
    for _ in range(6):
        lines.append(_xattr_tail(r))

    # Small payloads for write/ioctl buffers
    for _ in range(8):
        lines.append(_payload(r, 1, 128))

    # Ensure no empty lines, cap each length, and keep total size <= 4096
    normed: List[str] = []
    total = 0
    for s in lines:
        if not s:
            continue
        if len(s) > 512:
            s = s[:512]
        # Avoid producing reserved single dots for typical path args unless intended
        if s in ("",):
            continue
        b = (s + "\n").encode("utf-8", errors="ignore")
        if total + len(b) > 4096:
            break
        normed.append(s)
        total += len(b)

    return ("\n".join(normed) + "\n").encode("utf-8")
